using Microsoft.EntityFrameworkCore;namespace AssetForge.Infrastructure.Data;public static class Phase4Upgrade{public static async Task ApplyAsync(AssetForgeDbContext db){await db.Database.ExecuteSqlRawAsync("CREATE TABLE IF NOT EXISTS MaintenanceRecords (Id INTEGER NOT NULL CONSTRAINT PK_MaintenanceRecords PRIMARY KEY AUTOINCREMENT, AssetId INTEGER NOT NULL, Issue TEXT NOT NULL, Supplier TEXT NULL, Status TEXT NOT NULL, Cost TEXT NULL, OpenedUtc TEXT NOT NULL, CompletedUtc TEXT NULL, Resolution TEXT NULL, LoggedBy TEXT NOT NULL, CONSTRAINT FK_MaintenanceRecords_Assets_AssetId FOREIGN KEY (AssetId) REFERENCES Assets (Id) ON DELETE NO ACTION)");await db.Database.ExecuteSqlRawAsync("CREATE TABLE IF NOT EXISTS Suppliers (Id INTEGER NOT NULL CONSTRAINT PK_Suppliers PRIMARY KEY AUTOINCREMENT, Name TEXT NOT NULL, Email TEXT NULL, Phone TEXT NULL)");}}
